import os,re

def clean(s):
    s=s.replace('\n',' ').strip()
    if '>' in s:
        s=s.split('>',1)[1]
    else:
        return None
    s=s.replace('_',' ')
    s=re.sub(r'[^A-Za-z0-9, .\-]','',s)
    s=re.sub(r'\s+',' ',s).strip()
    return s.lower()

events=[]
cur=[]
start=None
for i in range(1,701):
    p=f'/app/cmdocr/{i:05d}.txt'
    if not os.path.exists(p):
        continue
    raw=open(p,errors='ignore').read().strip()
    t=clean(raw)
    if t is None:
        continue
    if t=='':
        if cur:
            # choose most complete candidate by longest alnum prefix sequence? for now longest string
            best=max(cur,key=lambda x:(len(x),x))
            events.append((start,i-1,best))
            cur=[]; start=None
    else:
        if not cur: start=i
        cur.append(t)
if cur:
    best=max(cur,key=lambda x:(len(x),x))
    events.append((start,700,best))
for a,b,s in events:
    print(f'{a:04d}-{b:04d} {s!r}')
print('events',len(events))
